"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[284],{8453(n,e,o){o.d(e,{R:()=>s,x:()=>a});var t=o(6540);const r={},i=t.createContext(r);function s(n){const e=t.useContext(i);return t.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function a(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(r):n.components||r:s(n.components),t.createElement(i.Provider,{value:e},n.children)}},9723(n,e,o){o.r(e),o.d(e,{assets:()=>c,contentTitle:()=>a,default:()=>p,frontMatter:()=>s,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"questions/ozon tech/4 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435","title":"4 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435","description":"","source":"@site/docs/questions/ozon tech/4 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435.md","sourceDirName":"questions/ozon tech","slug":"/questions/ozon tech/4 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435","permalink":"/interviews/docs/questions/ozon tech/4 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"3","permalink":"/interviews/docs/questions/ozon tech/3"},"next":{"title":"1 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435","permalink":"/interviews/docs/questions/ozon tech/1 \u043c\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435"}}');var r=o(4848),i=o(8453);const s={},a=void 0,c={},l=[];function u(n){const e={code:"code",pre:"pre",...(0,i.R)(),...n.components};return(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-cs",children:"interface IBookingTourService\n{\n    // \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u044b - UserInfo, FlightInfo, RentInfo, TourInfo\n    public bool BookTour(string userId, DateTime start, DateTime end, int hotelId, string roomType, string flightClass,\n        int flightNumber, int airCompanyId);\n}\n\npublic class BookingTourService : IBookingTourService\n{\n    private readonly IAirWaysService _airWaysService;\n    private readonly IHotelService _hotelService;\n    private readonly IUserHttpClient _userHttpClient;\n    private readonly IUnitOfWork _unitOfWork;\n    private readonly IBookingTourRepository _tourRepository;\n\n    // \u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0433\u0430\u0439\u0434\u043b\u0430\u0439\u043d\u044b \u043f\u043e \u0441\u0442\u0430\u0442\u0438\u043a \u043f\u043e\u043b\u044f\u043c\n    // \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u044b \u0431\u044b\u0442\u044c static\n    // \u0441\u043f\u0440\u044f\u0442\u0430\u0442\u044c \u0432\u043d\u0443\u0442\u0440\u044c \u043c\u0435\u0442\u043e\u0434\u0430 BookTour\n    private static Guid _reservationIdAir;\n    private static Guid _reservationIdHotel;\n\n    // \u041c\u043e\u0436\u043d\u043e \u0443\u0434\u0430\u043b\u0438\u0442\u044c, \u0442. \u043a. \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f\n    public static long _countBooked;\n\n    // Primary constructor\n    public BookingTourService(IAirWaysService airWaysService, IHotelService hotelService,\n        IUserHttpClient userHttpClient, IUnitOfWork unitOfWork, IBookingTourRepository tourRepository)\n    {\n        _airWaysService = airWaysService;\n        _hotelService = hotelService;\n        _userHttpClient = userHttpClient;\n        _unitOfWork = unitOfWork;\n        _tourRepository = tourRepository;\n    }\n\n\n    // async Task\n    public bool BookTour(string userId, DateTime start, DateTime end, int hotelId, string roomType, string flightClass,\n        int airCompanyId, int flightnumber)\n    {\n        try\n        {\n            var flightInfo = new FlightInfo(Enum.Parse<FlightClass>(flightClass), airCompanyId, flightnumber); // naming\n            var resultBookFlight = _airWaysService.Book(GetUser(userId), flightInfo);\n\n            var rentInfo = new RentInfo(start, end, hotelId, Enum.Parse<RoomType>(roomType));\n            var resultBookHotel = _hotelService.Book(GetUser(userId), rentInfo);\n\n            // await\n            // \u041d\u0435\u043f\u043e\u043d\u044f\u0442\u043d\u043e, \u043a\u0442\u043e \u0438\u0437 \u043d\u0438\u0445 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u0441\u044f \u043f\u0435\u0440\u0432\u044b\u043c, \u0438 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c CancelBook\n            Task.WhenAll(resultBookFlight, resultBookHotel);\n\n            _reservationIdAir = resultBookFlight.Result;\n            _reservationIdHotel = resultBookHotel.Result;\n        }\n        catch (BookFlightException)\n        {\n            // await\n            _hotelService.CancelBook(_reservationIdAir); // _reservationIdHotel\n            // throw;\n            return false;\n        }\n        catch (BookHotelException)\n        {\n            // await\n            _airWaysService.CancelBook(_reservationIdHotel); // _reservationIdAir\n            // throw;\n            return false;\n        }\n        catch (Exception ex)\n        {\n            // throw;\n            // \n            throw new ApplicationException(ex.Message, ex);\n        }\n        finally\n        {\n            // ExecuteAsync\n            // \u0422\u0443\u0440 \u0441\u043e\u0437\u0434\u0430\u0441\u0442\u0441\u044f \u0432 \u043b\u044e\u0431\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u0442\u043e\u0433\u043e, \u0437\u0430\u0431\u0440\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043b\u0438\u0441\u044c \u043b\u0438 \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438\n            // await\n            _unitOfWork.Execute(async () =>\n            {\n                // await _tourRepository.Save(tour)\n                await _tourRepository.Save(_reservationIdAir, _reservationIdHotel, GetUser(userId));\n            }).RunSynchronously(); // Remove RunSynchronously\n            _countBooked++; // Interlocked.Increment();\n        }\n\n        return true; // \u0443\u0434\u0430\u043b\u0438\u0442\u044c\n    }\n\n    // Task<UserInfo>\n    private UserInfo GetUser(string userId)\n    {\n        // remove long.Parse\n        // await \n        // try-catch\n        return _userHttpClient.GetUserById(long.Parse(userId)).Result;\n    }\n}\n\n// \u0412\u0441\u0435 \u0447\u0442\u043e \u043d\u0438\u0436\u0435 \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u0432 \u043a\u043e\u0434\u043e\u0432\u043e\u0439 \u0431\u0430\u0437\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430, \u0440\u0435\u0432\u044c\u044e \u043d\u0435 \u043f\u043e\u043b\u0435\u0436\u0438\u0442\n\npublic interface IAirWaysService\n{\n    Task<Guid> Book(UserInfo user, FlightInfo flightInfo, CancelationToken ct = CancelationToken.None);\n    Task CancelBook(Guid reservationId, CancelationToken ct = CancelationToken.None);\n}\n\npublic interface IHotelService\n{\n    Task<Guid> Book(UserInfo user, RentInfo rentInfo, CancelationToken ct = CancelationToken.None);\n    Task CancelBook(Guid reservationId, CancelationToken ct = CancelationToken.None);\n}\n\npublic interface IBookingTourRepository\n{\n    Task Save(Guid reservationAirId, Guid reservationHotelId, UserInfo user,\n        CancelationToken ct = CancelationToken.None);\n}\n\npublic interface IUserHttpClient\n{\n    Task<UserInfo> GetUserById(long userId, CancelationToken ct = CancelationToken.None);\n}\n\npublic interface IUnitOfWork\n{\n    Task Execute(Func<Task> action);\n}\n\npublic class BookFlightException : Exception\n{\n}\n\npublic class BookHotelException : Exception\n{\n}\n\npublic record FlightInfo(FlightClass flightClass, long airCompanyId, long flightNumber);\n\npublic record RentInfo(DateTimeOffset start, DateTimeOffset end, long hotelid, RoomType roomType);\n\npublic record UserInfo(long userId, string userName);\n\npublic enum FlightClass\n{\n    First = 1,\n    Business = 2,\n    Economy = 3\n}\n\npublic enum RoomType\n{\n    Classic = 1,\n    Luxury = 2\n}\n"})})}function p(n={}){const{wrapper:e}={...(0,i.R)(),...n.components};return e?(0,r.jsx)(e,{...n,children:(0,r.jsx)(u,{...n})}):u(n)}}}]);